module monte_carlo_pi(
    input wire [7:0] random_x,
    input wire [7:0] random_y,
    input wire start,
    output reg [31:0] pi_estimate,
    output reg valid
);
    reg [31:0] inside_circle;
    reg [31:0] total_points;

    initial begin
        inside_circle = 0;
        total_points = 0;
        pi_estimate = 0;
        valid = 0;
    end

    always @(posedge start) begin
        total_points = total_points + 1;
        if ((random_x * random_x + random_y * random_y) <= 255*255) begin
            inside_circle = inside_circle + 1;
        end
        pi_estimate = (inside_circle * 4) / total_points;
        valid = 1;
    end
