module WatchdogTimer (
    input clk,
    input reset,
    output reg timeout
);
    parameter TIMEOUT_THRESHOLD = 5; // Number of clock cycles before timeout
    reg [2:0] counter; // 3-bit counter for timeout

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 3'b000;
            timeout <= 1'b0;
        end else begin
            if (counter < TIMEOUT_THRESHOLD - 1) begin
                counter <= counter + 1;
                timeout <= 1'b0;
            end else begin
                timeout <= 1'b1;
            end
        end
    end
endmodule

