module dma_controller (
    input wire clk,
    input wire rst_n,
    input wire [3:0] req,  // Request signals from 4 channels
    output reg [3:0] gnt,   // Grant signal to the selected channel
    output reg done         // Transfer done signal
);

    reg [1:0] state;       // State of the state machine
    reg [1:0] current_channel;  // Current channel being processed

    parameter IDLE = 2'b00, TRANSFER = 2'b01, DONE = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            gnt <= 4'b0000;
            done <= 0;
            current_channel <= 0;
        end else begin
            case (state)
                IDLE: begin
                    gnt <= 4'b0000;
                    done <= 0;
                    if (req != 4'b0000) begin
                        state <= TRANSFER;
                        current_channel <= 0;
                    end
                end
                TRANSFER: begin
                    if (req[current_channel]) begin
                        gnt <= (1 << current_channel);
                        // Simulate data transfer
                        state <= DONE;
                    end else begin
                        current_channel <= (current_channel + 1) % 4;
                    end
                end
                DONE: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

