module SRT_Divider (
    input clk,
    input reset,
    input [15:0] numerator,
    input [15:0] denominator,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] A; // Numerator
    reg [15:0] B; // Denominator
    reg [15:0] Q; // Quotient
    reg [15:0] R; // Remainder
    reg [3:0] state; // State variable
    reg [4:0] bit_count; // Count the bits processed

    localparam IDLE = 0, LOAD = 1, DIVIDE = 2, OUTPUT = 3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            quotient <= 0;
            remainder <= 0;
            done <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (numerator != 0 && denominator != 0) begin
                        A <= numerator;
                        B <= denominator;
                        Q <= 0;
                        R <= 0;
                        bit_count <= 15; // Process 16 bits
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    // Start the division process
                    if (bit_count >= 0) begin
                        R <= {R[14:0], A[15]}; // Shift in bit from A
                        A <= {A[14:0], 1'b0};  // Shift A
                        if (R >= B) begin
                            R <= R - B;
                            Q[bit_count] <= 1;
                        end else begin
                            Q[bit_count] <= 0;
                        end
                        bit_count <= bit_count - 1;
                    end else begin
                        state <= OUTPUT;
                    end
                end
                OUTPUT: begin
                    quotient <= Q;
                    remainder <= R;
                    done <= 1; // Indicate completion
                    state <= IDLE; // Go back to IDLE
                end
            endcase
        end
    end
endmodule

