module sample_rate_converter (
    input clk_in,
    input clk_out,
    input rst,
    input in_signal,
    output reg out_signal
);
    reg [3:0] sample_count;
    reg [1:0] avg_sum;
    reg [1:0] sample_buffer;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            sample_count <= 0;
            avg_sum <= 0;
        end else begin
            sample_buffer[sample_count] <= in_signal;
            sample_count <= sample_count + 1;

            if (sample_count == 3) begin
                avg_sum <= sample_buffer[0] + sample_buffer[1] + sample_buffer[2] + sample_buffer[3];
                sample_count <= 0; // Reset for next sample batch
            end
        end
    end

    always @(posedge clk_out or posedge rst) begin
        if (rst) begin
            out_signal <= 0;
        end else begin
            out_signal <= avg_sum[1]; // Only output the MSB for simplicity
        end
    end
endmodule

