module crc_generator(  
    input clk,  
    input reset,  
    input start,  
    input [15:0] data_in,  
    output reg [15:0] crc_out,  
    output reg done  
);  
    reg [15:0] crc;  
    reg [4:0] bit_count;  
    reg state; // 0: idle, 1: calculating  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            crc <= 16'hFFFF;  
            bit_count <= 0;  
            crc_out <= 0;  
            done <= 0;  
            state <= 0;  
        end else begin  
            case (state)  
                0: begin  
                    if (start) begin  
                        crc <= 16'hFFFF;  
                        bit_count <= 0;  
                        state <= 1;  
                        done <= 0;  
                    end  
                end  
                1: begin  
                    if (bit_count < 16) begin  
                        crc <= (crc >> 1) ^ (data_in[15-bit_count] ? 16'hA001 : 16'h0000);  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        crc_out <= crc;  
                        done <= 1;  
                        state <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

