module RRT (
    input clk,
    input rst,
    input [15:0] start_x,
    input [15:0] start_y,
    input [15:0] goal_x,
    input [15:0] goal_y,
    output reg found
);
    reg [15:0] current_x;
    reg [15:0] current_y;
    reg [15:0] random_x;
    reg [15:0] random_y;
    reg [3:0] state;

    initial begin
        found = 0;
        current_x = start_x;
        current_y = start_y;
        state = 0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            found <= 0;
            current_x <= start_x;
            current_y <= start_y;
            state <= 0;
        end else begin
            case (state)
                0: begin
                    // Randomly generate new node
                    random_x <= $random % 1024; // Random x in [0, 1023]
                    random_y <= $random % 1024; // Random y in [0, 1023]
                    state <= 1;
                end
                1: begin
                    // Check if we can connect to the random node
                    // Simple distance check to "connect"
                    if ((random_x - current_x) ** 2 + (random_y - current_y) ** 2 < 10000) begin
                        current_x <= random_x;
                        current_y <= random_y;
                        // Check if we reached the goal
                        if ((current_x == goal_x) && (current_y == goal_y)) begin
                            found <= 1;
                        end
                    end
                    state <= 0; // Go back to state 0
                end
            endcase
        end
    end
endmodule

module crc_generator(clk, reset, data_in, poly, crc_out);  
    input clk;  
    input reset;  
    input [15:0] data_in;  
    input [15:0] poly;  
    output reg [15:0] crc_out;  

    reg [15:0] crc;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            crc <= 16'h0000;  
        end else begin  
            crc <= crc ^ data_in;  
            for (i = 15; i >= 0; i = i - 1) begin  
                if (crc[15]) begin  
                    crc <= (crc << 1) ^ poly;  
                end else begin  
                    crc <= crc << 1;  
                end  
            end  
            crc_out <= crc;  
        end  
    end  
endmodule

