module kalman_filter #(parameter DATA_WIDTH = 16) (  
    input clk,  
    input rst,  
    input [DATA_WIDTH-1:0] measurement,  
    input [DATA_WIDTH-1:0] state_estimate,  
    input [DATA_WIDTH-1:0] process_noise,  
    input [DATA_WIDTH-1:0] measurement_noise,  
    output reg [DATA_WIDTH-1:0] updated_state_estimate,  
    output reg [DATA_WIDTH-1:0] updated_error_covariance  
);  

    reg [DATA_WIDTH-1:0] kalman_gain;  
    reg [DATA_WIDTH-1:0] error_covariance;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            updated_state_estimate <= 0;  
            updated_error_covariance <= 0;  
        end else begin  
            // Update error covariance  
            error_covariance <= process_noise + measurement_noise;  

            // Calculate Kalman Gain  
            kalman_gain <= error_covariance / (error_covariance + measurement_noise);  

            // Update state estimate  
            updated_state_estimate <= state_estimate + kalman_gain * (measurement - state_estimate);  

            // Update error covariance  
            updated_error_covariance <= (1 - kalman_gain) * error_covariance;  
        end  
    end  
endmodule

