module debounce (
    input wire clk,
    input wire rst,
    input wire button_in,
    output reg button_out
);
    parameter DEBOUNCE_TIME = 20; // Adjust the debounce time as needed
    reg [3:0] counter;
    reg button_sync_0;
    reg button_sync_1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            button_out <= 0;
            counter <= 0;
            button_sync_0 <= 0;
            button_sync_1 <= 0;
        end else begin
            button_sync_0 <= button_in;
            button_sync_1 <= button_sync_0;

            if (button_sync_1 != button_out) begin
                counter <= 0; // Reset the counter on edge detection
            end

            if (counter < DEBOUNCE_TIME) begin
                counter <= counter + 1;
            end else if (button_sync_1 == button_out) begin
                button_out <= button_sync_1; // Update output if stable
            end
        end
    end
endmodule

