    output reg [7:0] remainder,  
    output reg done  
);  
    reg [3:0] state;  
    reg [7:0] current_dividend;  
    reg [7:0] current_quotient;  
    reg [7:0] temp_remainder;  
    parameter IDLE = 4'b0000,  
              DIVIDE = 4'b0001,  
              DONE = 4'b0010;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            quotient <= 8'b0;  
            remainder <= 8'b0;  
            done <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        current_dividend <= dividend;  
                        current_quotient <= 8'b0;  
                        temp_remainder <= 8'b0;  
                        state <= DIVIDE;  
                        done <= 0;  
                    end  
                end  
                DIVIDE: begin  
                    if (current_dividend >= divisor) begin  
                        current_dividend <= current_dividend - divisor;  
                        current_quotient <= current_quotient + 1;  
                    end else begin  
                        temp_remainder <= current_dividend;  
                        quotient <= current_quotient;  
                        remainder <= temp_remainder;  
                        state <= DONE;  
                    end  
                end  
                DONE: begin  
                    done <= 1;  
                end  
            endcase  
        end  
    end  
endmodule

