module dma_controller(  
    input clk,  
    input reset,  
    input [7:0] enable,  
    input [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg [7:0] transfer_complete  
);  

reg [7:0] channel_data;  
reg [2:0] current_channel;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        data_out <= 8'b0;  
        transfer_complete <= 8'b0;  
        current_channel <= 3'b0;  
    end else begin  
        if (enable[current_channel]) begin  
            data_out <= data_in;  
            transfer_complete[current_channel] <= 1;  
        end else begin  
            transfer_complete[current_channel] <= 0;  
        end  
        current_channel <= current_channel + 1;  
        if (current_channel == 7) begin  
            current_channel <= 0;  
        end  
    end  
end  

endmodule

module kalman_filter (  
    input clk,  
    input reset,  
    input signed [15:0] measurement,  
    output reg signed [15:0] estimated_state  
);  
    reg signed [15:0] state_estimate;  
    reg signed [15:0] kalman_gain;  
    reg signed [15:0] process_noise;  
    reg signed [15:0] measurement_noise;  

    initial begin  
        state_estimate = 0;  
        process_noise = 16'h0001;  
        measurement_noise = 16'h0001;  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state_estimate <= 0;  
        end else begin  
            // Prediction step  
            // (Assuming a simple model where next state is same as current state)  
            estimated_state <= state_estimate;  
            // Update step  
            kalman_gain <= process_noise / (process_noise + measurement_noise);  
            state_estimate <= state_estimate + kalman_gain * (measurement - state_estimate);  
        end  
    end  
endmodule

module divider (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] numerator,
    input wire [7:0] denominator,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [7:0] temp_numerator;
    reg [7:0] temp_denominator;
    reg [3:0] count;
    reg state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 8'b0;
            remainder <= 8'b0;
            done <= 0;
            count <= 4'b0;
            state <= 0;
        end else if (start) begin
            temp_numerator <= numerator;
            temp_denominator <= denominator;
            quotient <= 8'b0;
            remainder <= 8'b0;
            count <= 4'b0;
            done <= 0;
            state <= 1;
        end else if (state) begin
            if (count < 8) begin
                remainder <= {remainder[6:0], temp_numerator[7]}; // Shift in numerator
                temp_numerator <= {temp_numerator[6:0], 1'b0}; // Shift left numerator
                if (remainder >= temp_denominator) begin
                    remainder <= remainder - temp_denominator;
                    quotient[count] <= 1;
                end
                count <= count + 1;
            end else begin
                done <= 1;
                state <= 0;
            end
        end
    end
endmodule

module MatrixInverse (
    input [31:0] matrix_in, // Flattened 2x2 matrix (a, b, c, d)
    output reg [31:0] matrix_out // Flattened 2x2 inverse matrix (a', b', c', d')
);
    wire [31:0] det;
    wire [31:0] a, b, c, d;

    assign a = matrix_in[31:24];
    assign b = matrix_in[23:16];
    assign c = matrix_in[15:8];
    assign d = matrix_in[7:0];

    assign det = a * d - b * c; // Determinant

    always @(*) begin
        if (det != 0) begin
            matrix_out[31:24] = d / det; // a'
            matrix_out[23:16] = -b / det; // b'
            matrix_out[15:8] = -c / det; // c'
            matrix_out[7:0] = a / det; // d'
        end else begin
            matrix_out = 32'hFFFFFFFF; // Indicate non-invertible
        end
    end
endmodule

module priority_arbiter(  
    input wire req0,  
    input wire req1,  
    input wire req2,  
    input wire req3,  
    output reg grant  
);  
    always @(*) begin  
        if (req0)  
            grant = 1;  
        else if (req1)  
            grant = 2;  
        else if (req2)  
            grant = 3;  
        else if (req3)  
            grant = 4;  
        else  
            grant = 0;  
    end  
endmodule

module reset_controller(  
    input clk,  
    input async_res,  
    input [3:0] reset_duration,  
    output reg reset_out,  
    output reg reset_status  
);  
    reg [3:0] counter;  
    reg async_res_d;  

    always @(posedge clk or negedge async_res) begin  
        if (!async_res) begin  
            reset_out <= 1;  
            reset_status <= 1;  
            counter <= reset_duration;  
        end else if (counter > 0) begin  
            counter <= counter - 1;  
        end else begin  
            reset_out <= 0;  
            reset_status <= 0;  
        end  
    end  
endmodule

