module PLL (
    input wire clk_in,
    input wire reset,
    output reg clk_out,
    output reg locked
);
    reg [1:0] phase_detector; // 0: no lock, 1: locked, 2: out of phase
    reg [3:0] vco_count;      // VCO counter

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            vco_count <= 0;
            clk_out <= 0;
            locked <= 0;
            phase_detector <= 0;
        end else begin
            // Simple phase detector logic
            if (vco_count < 4) begin
                phase_detector <= 1; // locked
                locked <= 1;
