module spi_master (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    input wire clk_polarity,
    input wire clk_phase,
    output reg mosi,
    output reg sclk,
    output reg cs,
    output reg [7:0] data_out,
    output reg done
);
    reg [3:0] bit_cnt;
    reg [7:0] shift_reg;
    reg state;

    localparam IDLE = 1'b0, TRANSFER = 1'b1;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            mosi <= 0;
            sclk <= 0;
            cs <= 1;
            data_out <= 8'b0;
            done <= 0;
            bit_cnt <= 4'b0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        cs <= 0; // Assert chip select
                        shift_reg <= data_in;
                        bit_cnt <= 4'b0;
                        state <= TRANSFER;
                        done <= 0;
                    end
                end
                TRANSFER: begin
                    if (bit_cnt < 8) begin
                        sclk <= clk_polarity ^ (clk_phase ? ~sclk : sclk); // Control clock based on polarity and phase
                        mosi <= shift_reg[7]; // Send the most significant bit
                        shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        cs <= 1; // Deassert chip select
                        data_out <= shift_reg; // Capture received data
                        done <= 1; // Mark as done
                        state <= IDLE; // Return to idle state
                    end
                end
            endcase
        end
    end
endmodule

