module simple_DES(  
    input wire [63:0] plaintext,  
    input wire [55:0] key,  
    input wire clk,  
    input wire rst,  
    output reg [63:0] ciphertext  
);  
    // Internal state  
    reg [63:0] state;  
    reg [55:0] round_key;  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            ciphertext <= 64'b0;  
            state <= plaintext;  
            round_key <= key;  
        end else begin  
            // Simplified encryption process  
            for (i = 0; i < 16; i = i + 1) begin  
                // XOR with round key (not a real DES function)  
                state <= state ^ {round_key, 8'b0};  
                // Simple rotation to mimic the DES structure  
                state <= {state[62:0], state[63]};  
            end  
            ciphertext <= state;  
        end  
    end  
endmodule

