module sliding_window_protocol #(parameter WINDOW_SIZE = 4, parameter FRAME_SIZE = 8) (  
    input clk,  
    input reset,  
    input send,  
    input [FRAME_SIZE-1:0] data_in,  
    input [WINDOW_SIZE-1:0] ack,  
    output reg [WINDOW_SIZE-1:0] sent_frames,  
    output reg [WINDOW_SIZE-1:0] acknowledged_frames  
);  

    reg [WINDOW_SIZE-1:0] window;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            sent_frames <= 0;  
            acknowledged_frames <= 0;  
            window <= 1;  
        end else if (send && (sent_frames < window)) begin  
            sent_frames <= sent_frames + 1;  
            window <= window + 1;  
        end  

        for (i = 0; i < WINDOW_SIZE; i = i + 1) begin  
            if (ack[i] == 1) begin  
                acknowledged_frames[i] <= 1;  
            end  
        end  

        // Adjust the window based on acknowledged frames  
        window <= window - acknowledged_frames;  
    end  
endmodule

