module bilinear_interpolation (
    input [15:0] Q11,
    input [15:0] Q12,
    input [15:0] Q21,
    input [15:0] Q22,
    input [7:0] u,
    input [7:0] v,
    output [15:0] Q
);
    wire [15:0] R1, R2, R3, R4;
    wire [15:0] uv_product;

    // Calculate R1 and R2
    assign R1 = Q11 + ((Q21 - Q11) * u) >> 8; // Q11 + (Q21 - Q11) * u / 256
    assign R2 = Q12 + ((Q22 - Q12) * u) >> 8; // Q12 + (Q22 - Q12) * u / 256

    // Calculate R3
    assign R3 = R1 + ((R2 - R1) * v) >> 8; // R1 + (R2 - R1) * v / 256

    // Final output
    assign Q = R3; // Q is the interpolated value

endmodule

module float_multiplier (
    input [31:0] a,
    input [31:0] b,
    output [31:0] result
);

    wire [7:0] exponent_a;
    wire [7:0] exponent_b;
    wire [7:0] exponent_result;
    wire [22:0] mantissa_a;
    wire [22:0] mantissa_b;
    wire [47:0] mantissa_result;

    assign exponent_a = a[30:23];
    assign exponent_b = b[30:23];
    assign mantissa_a = {1'b1, a[22:0]};
    assign mantissa_b = {1'b1, b[22:0]};

    assign exponent_result = exponent_a + exponent_b - 8'd127; // Bias adjustment

    assign mantissa_result = mantissa_a * mantissa_b;

    assign result = {exponent_result, mantissa_result[46:24]}; // Take the top 23 bits for the result

endmodule

