module rsa_encrypt(
    input [15:0] plaintext,
    input [15:0] exponent,
    input [15:0] modulus,
    input clk,
    input rst,
    output reg [15:0] ciphertext
);
    reg [15:0] result;
    reg [15:0] base;
    reg [15:0] exp;
    reg [15:0] mod;
    reg [3:0] state;

    parameter IDLE = 4'b0000, LOAD = 4'b0001, EXP_LOOP = 4'b0010, MOD_LOOP = 4'b0011, DONE = 4'b0100;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            result <= 16'b1;
            base <= 0;
            exp <= 0;
            mod <= 0;
            ciphertext <= 0;
        end else begin
            case (state)
                IDLE: begin
                    base <= plaintext;
                    exp <= exponent;
                    mod <= modulus;
                    state <= LOAD;
                end
                LOAD: begin
                    if (exp > 0) begin
                        if (exp[0] == 1) begin
                            result <= (result * base) % mod;
                        end
                        base <= (base * base) % mod;
                        exp <= exp >> 1;
                    end else begin
                        ciphertext <= result;
                        state <= DONE;
                    end
                end
                DONE: begin
                    state <= IDLE; // Reset to idle for next operation
                end
            endcase
        end
    end
endmodule

