module PID_Controller (
    input wire clk,
    input wire reset,
    input wire [15:0] setpoint,     // Target value
    input wire [15:0] measurement,   // Current value
    input wire [15:0] Kp,            // Proportional gain
    input wire [15:0] Ki,            // Integral gain
    input wire [15:0] Kd,            // Derivative gain
    output reg [15:0] control_signal  // Output control signal
);

    reg [15:0] prev_error;
    reg [31:0] integral; // Use a larger bit-width for integral to avoid overflow
    reg [15:0] error;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            control_signal <= 0;
            prev_error <= 0;
            integral <= 0;
        end else begin
            error <= setpoint - measurement;
            integral <= integral + error; // Accumulating integral
            control_signal <= (Kp * error) + (Ki * integral[15:0]) + (Kd * (error - prev_error)); // PID computation
            prev_error <= error; // Update previous error
        end
    end
endmodule

